<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad, onPullDownRefresh, onShow } from '@dcloudio/uni-app'
import { distributionApi } from '../../api/distribution.api'
import type { DistributionFilterOption, DistributionShelf, DistributionSummary } from '../../models/distribution'
import WareState from '@/shared/components/WareState.vue'
import SessionDatePicker from '@/shared/components/SessionDatePicker.vue'
import SessionTrigger from '@/shared/components/SessionTrigger.vue'
import { sessionStore } from '@/store/session'

const date=ref(new Date().toISOString().slice(0,10)),status=ref<'pending'|'completed'>('pending'),keyword=ref(''),loading=ref(true),error=ref('')
const sessionPickerVisible=ref(false)
const warehouseType=ref<'normal'|'city'>('normal'),selfPickup=ref(false),earlyShift=ref(false),restock=ref(false),zone=ref(''),segments=ref<string[]>([])
const selectorVisible=ref(false),draftZone=ref(''),draftSegments=ref<string[]>([])
const summary=ref<DistributionSummary>({totalShelves:0,pendingShelves:0,completedShelves:0,totalUnits:0,allocatedUnits:0,restockUnits:0})
const allShelves=ref<DistributionShelf[]>([]),options=ref<DistributionFilterOption[]>([])
const shelves=computed(()=>allShelves.value.filter(row=>status.value==='completed'?row.completed:!row.completed))
const regionLabel=computed(()=>!zone.value?'全部分区':`${options.value.find(item=>item.zone===zone.value)?.areaName||`${Number(zone.value)}区`}${segments.value.length?` / ${segments.value.map(value=>`${value}段`).join('、')}`:''}`)
const allDraftSegments=computed(()=>options.value.find(value=>value.zone===draftZone.value)?.segments||[])
const progress=computed(()=>summary.value.totalUnits?Math.round(summary.value.allocatedUnits/summary.value.totalUnits*100):0)

async function load(){loading.value=true;error.value='';try{[options.value,allShelves.value]=await Promise.all([distributionApi.filterOptions(date.value,warehouseType.value),distributionApi.shelves(date.value,'all',keyword.value,{warehouseType:warehouseType.value,selfPickup:selfPickup.value,earlyShift:earlyShift.value,restock:restock.value,zone:zone.value,segments:segments.value})]);summary.value={totalShelves:allShelves.value.length,pendingShelves:allShelves.value.filter(v=>!v.completed).length,completedShelves:allShelves.value.filter(v=>v.completed).length,totalUnits:allShelves.value.reduce((n,v)=>n+v.totalUnits,0),allocatedUnits:allShelves.value.reduce((n,v)=>n+v.allocatedUnits,0),restockUnits:allShelves.value.reduce((n,v)=>n+v.restockUnits,0)}}catch(e){error.value=e instanceof Error?e.message:'配货数据加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
function changeWarehouse(value:'normal'|'city'){warehouseType.value=value;zone.value='';segments.value=[];load()}
function toggleFilter(name:'selfPickup'|'earlyShift'|'restock'){if(name==='selfPickup')selfPickup.value=!selfPickup.value;if(name==='earlyShift')earlyShift.value=!earlyShift.value;if(name==='restock')restock.value=!restock.value;load()}
function openSelector(){draftZone.value=zone.value;draftSegments.value=[...segments.value];selectorVisible.value=true}
function chooseDraftZone(value:string){draftZone.value=value;draftSegments.value=value?[...(options.value.find(option=>option.zone===value)?.segments||[])]:[]}
function toggleDraftSegment(value:string){if(!draftZone.value||!allDraftSegments.value.includes(value))return;draftSegments.value=draftSegments.value.includes(value)?draftSegments.value.filter(segment=>segment!==value):[...draftSegments.value,value]}
function confirmSelector(){zone.value=draftZone.value;segments.value=[...draftSegments.value];selectorVisible.value=false;load()}
function openShelf(row:DistributionShelf){uni.navigateTo({url:`/features/distribution/pages/shelf-detail/index?date=${date.value}&shelf=${encodeURIComponent(row.shelfNo)}`})}
function openUnfinished(){if(!sessionStore.can('distribution.unfinished.view'))return;uni.navigateTo({url:`/features/distribution/pages/unfinished-summary/index?date=${date.value}`})}
function openMine(){if(!sessionStore.can('distribution.mine.view'))return;uni.navigateTo({url:`/features/distribution/pages/my-allocations/index?date=${date.value}`})}
onLoad(q=>{if(q?.date)date.value=String(q.date);load()});onShow(load);onPullDownRefresh(load)
</script>

<template><view class="page">
  <view class="head"><SessionTrigger :value="date" @click="sessionPickerVisible=true"/><button v-if="sessionStore.can('distribution.mine.view')" class="mine-entry" @click="openMine">我的配货</button></view>
  <view class="warehouse-switch"><view :class="{active:warehouseType==='normal'}" @click="changeWarehouse('normal')">普通货架</view><view :class="{active:warehouseType==='city'}" @click="changeWarehouse('city')">城市仓</view></view>
  <view class="summary"><view><text>待配货</text><strong>{{summary.pendingShelves}}</strong><small>个货架</small></view><view><text>已配货</text><strong>{{summary.allocatedUnits}}</strong><small>/ {{summary.totalUnits}} 扎</small></view><view><text>待补货</text><strong>{{summary.restockUnits}}</strong><small>扎</small></view></view>
  <view class="progress"><view :style="{width:progress+'%'}"/></view>
  <view class="search"><text>⌕</text><input v-model="keyword" placeholder="搜索货位、供应商或花材" confirm-type="search" @confirm="load"/><text v-if="keyword" @click="keyword='';load()">清除</text></view>
  <view class="filter-row"><view :class="{active:selfPickup}" @click="toggleFilter('selfPickup')"><text class="box">{{selfPickup?'✓':''}}</text>自提</view><view :class="{active:earlyShift}" @click="toggleFilter('earlyShift')"><text class="box">{{earlyShift?'✓':''}}</text>早班</view><view :class="{active:restock}" @click="toggleFilter('restock')"><text class="box">{{restock?'✓':''}}</text>待补</view><view :class="['region-selector',{active:zone}]" @click="openSelector"><text class="region-value">{{zone?regionLabel:'分区/分段'}}</text><text class="filter-chevron" /></view></view>
  <view class="tabs"><view :class="{active:status==='pending'}" @click="status='pending'">可配货 {{summary.pendingShelves}}</view><view :class="{active:status==='completed'}" @click="status='completed'">配货完成 {{summary.completedShelves}}</view><view v-if="sessionStore.can('distribution.unfinished.view')" class="summary-entry" @click="openUnfinished">未配货汇总 <text class="entry-arrow" /></view></view>
  <WareState v-if="loading" type="loading" title="正在加载货架"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重新加载" @action="load"/>
  <view v-else-if="shelves.length" class="grid"><view v-for="row in shelves" :key="row.shelfNo" :class="['shelf',{'early-shelf':row.earlyShift}]" @click="openShelf(row)"><view class="shelf-top"><strong>#{{row.shelfNo}}</strong><text v-if="row.earlyShift" class="early">早班</text><text v-if="row.restockUnits" class="warn">待补 {{row.restockUnits}}</text><text v-if="row.deliveryType===2" class="tag">自提</text></view><text class="supplier">{{row.supplierNames}}</text><view class="meter"><view :style="{width:(row.totalUnits?row.allocatedUnits/row.totalUnits*100:0)+'%'}"/></view><view class="foot"><text>{{row.itemCount}} 项 · 问题 {{row.problemUnits}} 扎</text><b>{{row.allocatedUnits}}/{{row.totalUnits}}</b></view></view></view>
  <WareState v-else type="empty" title="当前筛选暂无货架" description="可切换仓库类型、取消筛选或调整分区分段"/>
  <view v-if="selectorVisible" class="drawer-mask" @click="selectorVisible=false"><view class="region-drawer" @click.stop>
    <view class="drawer-head"><text @click="selectorVisible=false">取消</text><strong>分区/分段选择</strong><text @click="confirmSelector">确定</text></view>
    <view class="segment-picker"><text class="segment-title">选择分段</text><view v-for="segment in ['1','2','3','4']" :key="segment" :class="['segment-check',{checked:draftSegments.includes(segment),disabled:!draftZone||!allDraftSegments.includes(segment)}]" @click="toggleDraftSegment(segment)"><text class="check-box">{{draftSegments.includes(segment)?'✓':''}}</text><text>{{segment}}段</text></view></view>
    <text class="drawer-hint">{{draftZone?'可调整当前分区已设置的分段':'请先选择分区，自动匹配已设置分段'}}</text>
    <scroll-view scroll-y class="zone-grid-scroll"><view class="zone-grid"><view :class="{selected:!draftZone}" @click="chooseDraftZone('')">全部分区</view><view v-for="entry in options" :key="entry.zone" :class="{selected:draftZone===entry.zone}" @click="chooseDraftZone(entry.zone)">{{entry.areaName||`${Number(entry.zone)}区`}}</view></view></scroll-view>
  </view></view>
  <SessionDatePicker v-model="date" v-model:visible="sessionPickerVisible" @confirm="load"/>
</view></template>

<style scoped lang="scss">
.page{min-height:100vh;padding:28rpx 24rpx 60rpx}.head{display:flex;align-items:flex-start;justify-content:space-between}.title,.sub{display:block}.title{font-size:40rpx;font-weight:800}.sub{margin-top:7rpx;color:var(--wms-text-secondary);font-size:23rpx}.scan{height:64rpx;margin:0;padding:0 22rpx;border:0;border-radius:999rpx;background:var(--wms-surface-soft);color:var(--wms-primary-700);font-size:22rpx;font-weight:700;line-height:64rpx}.warehouse-switch{display:grid;grid-template-columns:1fr 1fr;margin-top:20rpx;padding:6rpx;border-radius:16rpx;background:#e5eeec}.warehouse-switch view{height:58rpx;border-radius:12rpx;color:var(--wms-text-secondary);font-size:23rpx;line-height:58rpx;text-align:center}.warehouse-switch .active{background:#fff;color:var(--wms-primary-700);font-weight:750;box-shadow:0 3rpx 10rpx rgba(23,43,41,.08)}.summary{display:flex;margin-top:16rpx;padding:24rpx 4rpx;border-radius:24rpx;background:#fff;box-shadow:var(--wms-shadow-card)}.summary>view{display:flex;flex:1;align-items:center;flex-direction:column;border-right:1rpx solid var(--wms-border)}.summary>view:last-child{border:0}.summary text,.summary small{color:var(--wms-text-secondary);font-size:21rpx}.summary strong{margin:5rpx 0;font-size:39rpx}.progress{height:8rpx;margin:-8rpx 18rpx 0;border-radius:8rpx;background:#dce8e5}.progress view{height:100%;border-radius:8rpx;background:var(--wms-primary-700)}.search{display:flex;height:76rpx;align-items:center;gap:12rpx;margin-top:24rpx;padding:0 20rpx;border-radius:18rpx;background:#fff}.search input{min-width:0;flex:1;font-size:24rpx}.search>text:last-child{color:var(--wms-primary-700);font-size:22rpx}.filter-row{display:flex;gap:14rpx;margin-top:14rpx}.filter-row view{display:flex;height:58rpx;align-items:center;gap:8rpx;padding:0 18rpx;border-radius:14rpx;background:#e7eeec;color:var(--wms-text-secondary);font-size:22rpx}.filter-row .active{background:var(--wms-surface-soft);color:var(--wms-primary-700);font-weight:700}.box{display:flex;width:25rpx;height:25rpx;align-items:center;justify-content:center;border:2rpx solid #aebbb8;border-radius:6rpx;font-size:17rpx}.active .box{border-color:var(--wms-primary-700);background:var(--wms-primary-700);color:#fff}.zone-scroll,.segment-scroll{margin-top:15rpx;white-space:nowrap}.segment-scroll{margin-top:9rpx}.zone-row,.segment-row{display:inline-flex;gap:10rpx}.zone-row text,.segment-row text{padding:10rpx 18rpx;border-radius:999rpx;background:#e7eeec;color:var(--wms-text-secondary);font-size:21rpx}.zone-row .active,.segment-row .active{background:var(--wms-primary-700);color:#fff}.tabs{display:flex;height:82rpx;gap:38rpx;border-bottom:1rpx solid var(--wms-border)}.tabs view{position:relative;display:flex;align-items:center;color:var(--wms-text-secondary);font-size:25rpx}.tabs .active{color:var(--wms-primary-700);font-weight:750}.tabs .active:after{position:absolute;right:0;bottom:-1rpx;left:0;height:5rpx;border-radius:5rpx;background:var(--wms-primary-700);content:''}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18rpx;margin-top:20rpx}.shelf{min-width:0;padding:22rpx;border-radius:21rpx;background:#fff;box-shadow:var(--wms-shadow-card)}.early-shelf{box-shadow:inset 6rpx 0 #7770c8,var(--wms-shadow-card)}.shelf-top{display:flex;align-items:center;gap:8rpx}.shelf-top strong{min-width:0;flex:1;font-size:28rpx}.warn,.tag,.early{padding:4rpx 7rpx;border-radius:7rpx;background:#fff2df;color:#a55a00;font-size:17rpx}.tag{background:var(--wms-surface-soft);color:var(--wms-primary-700)}.early{background:#edf0ff;color:#5652a5}.supplier{display:block;overflow:hidden;margin-top:10rpx;color:var(--wms-text-secondary);font-size:20rpx;white-space:nowrap;text-overflow:ellipsis}.meter{height:8rpx;margin-top:18rpx;border-radius:8rpx;background:#e6eeec}.meter view{height:100%;border-radius:8rpx;background:var(--wms-primary-700)}.foot{display:flex;justify-content:space-between;margin-top:10rpx;color:var(--wms-text-secondary);font-size:18rpx}.foot b{color:var(--wms-text);font-size:20rpx}
.filter-row .region-selector{min-width:0;max-width:230rpx;gap:10rpx;padding-right:16rpx}.region-value{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.filter-chevron{box-sizing:border-box;width:12rpx;height:12rpx;flex:none;border-top:2rpx solid var(--wms-primary-700);border-right:2rpx solid var(--wms-primary-700);transform:rotate(45deg)}.drawer-mask{position:fixed;z-index:50;inset:0;display:flex;align-items:flex-end;background:rgba(15,28,26,.42)}.region-drawer{box-sizing:border-box;width:100%;max-height:88vh;padding:24rpx 24rpx calc(28rpx + env(safe-area-inset-bottom));border-radius:28rpx 28rpx 0 0;background:#fff}.drawer-head{display:grid;grid-template-columns:100rpx 1fr 100rpx;align-items:center}.drawer-head strong{font-size:30rpx;text-align:center}.drawer-head text{color:var(--wms-text-secondary);font-size:23rpx}.drawer-head text:last-child{color:var(--wms-primary-700);text-align:right}.segment-picker{display:flex;align-items:center;gap:18rpx;margin-top:27rpx;flex-wrap:wrap}.segment-title{color:var(--wms-primary-700);font-size:22rpx}.segment-check{display:flex;align-items:center;gap:7rpx;font-size:22rpx}.check-box{display:flex;width:32rpx;height:32rpx;align-items:center;justify-content:center;border:2rpx solid #aebbb8;border-radius:6rpx;color:#fff;font-size:20rpx}.segment-check.checked .check-box{border-color:var(--wms-primary-700);background:var(--wms-primary-700)}.segment-check.disabled{opacity:.36}.drawer-hint{display:block;margin-top:18rpx;padding-bottom:18rpx;border-bottom:1rpx solid var(--wms-border);color:var(--wms-danger);font-size:20rpx}.zone-grid-scroll{max-height:58vh;margin-top:20rpx}.zone-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14rpx}.zone-grid view{height:70rpx;border:2rpx solid transparent;border-radius:10rpx;background:#f0f2f2;font-size:23rpx;line-height:70rpx;text-align:center}.zone-grid .selected{border-color:var(--wms-primary-700);background:var(--wms-surface-soft);color:var(--wms-primary-700)}
.tabs .summary-entry{margin-left:auto;gap:8rpx;color:var(--wms-primary-700);font-size:22rpx}.entry-arrow{box-sizing:border-box;width:11rpx;height:11rpx;border-top:2rpx solid currentColor;border-right:2rpx solid currentColor;transform:rotate(45deg)}
</style>
<style scoped>.head{align-items:center;gap:20rpx}.head :deep(.session-trigger){flex:none}.mine-entry{height:60rpx;margin:0 0 0 auto;padding:0 22rpx;border:0;border-radius:999rpx;background:var(--wms-surface-soft);color:var(--wms-primary-700);font-size:22rpx;font-weight:700;line-height:60rpx;white-space:nowrap}.mine-entry:after{border:0}</style>
